import sys,json,bisect,ipaddress as ip
sys.path.insert(0,'/workspace'); sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp/tests')
import test_dp as D, validate
from reference import reference_runs
payload = open('/tmp/dpcase.json').read()
req=validate.parse_request(payload.encode())[0]
fib={}
for route,hop in req['initial']: fib[route]=hop
fibs=[dict(fib)]
for tx in req['transactions']:
    for op,route,hop in tx:
        if op=='set': fib[route]=hop
        elif route in fib: del fib[route]
    fibs.append(dict(fib))
hit,miss,dec=req['costs']
starts,hops=reference_runs(fibs[0])
bl=[(rep,[bisect.bisect_right(starts,int(ip.IPv6Address(a)))-1 for a in addrs]) for vv,rep,addrs in req['bursts'] if vv==0]
R=len(starts); C=6
# replicate the python DP with choice tracking
from test_dp import WIDTH, LANES, SCALE, BIG
weights=[0]*R; hitsets=[]
for rep,runs_of in bl:
    runs=[bisect.bisect_right(starts,a)-1 for a in []] # dummy
for rep,addrs in bl:
    for k in addrs: weights[k]+=rep
    hitsets.append((rep,set(addrs)))
wsum=[0]
for x in weights: wsum.append(wsum[-1]+x)
T=[[0]*(R+1) for _ in range(R+1)]
for rep,runs in hitsets:
    pc=[0]*(R+1)
    for k in range(R): pc[k+1]=pc[k]+(1 if k in runs else 0)
    for i in range(R):
        for j in range(i+1,R+1):
            if pc[j]>pc[i]: T[i][j]+=rep
def leaf(i,s,m,cached):
    P=(32+s*WIDTH[m]+63)//64
    coeff=(s+LANES[m]-1)//LANES[m]+dec[m]
    work=coeff*(wsum[i+s]-wsum[i])+P*(hit if cached else miss)*T[i][i+s]
    return work*SCALE+P
def internal(i,s,b,m,cached):
    P=(32+4*b+(b-1)*WIDTH[m]+63)//64
    coeff=((b-1)+LANES[m]-1)//LANES[m]+dec[m]
    work=coeff*(wsum[i+s]-wsum[i])+P*(hit if cached else miss)*T[i][i+s]
    return work*SCALE+P
def ok(i,s,m):
    if m==0: return True
    spread=starts[i+s-1]-starts[i]
    return spread<(1<<(64 if m==1 else 32))
INF=BIG
Fe=[[[INF]*(C+1) for _ in range(R+1)] for _ in range(R+1)]
Ge=[[[[INF]*(C+1) for _ in range(10)] for _ in range(R+1)] for _ in range(R+1)]
Fc=[[[None]*(C+1) for _ in range(R+1)] for _ in range(R+1)]
Gc=[[[[None]*(C+1) for _ in range(10)] for _ in range(R+1)] for _ in range(R+1)]
for s in range(1,R+1):
    bmax=min(9,s)
    for b in range(2,bmax+1):
        for i in range(0,R-s+1):
            for d in range(b-1,s):
                left=Ge[i][d][b-1]; right=Fe[i+d][s-d]
                for r1 in range(0,C+1):
                    if left[r1]>=INF: continue
                    for r2 in range(0,C+1-r1):
                        if right[r2]>=INF: continue
                        c=left[r1]+right[r2]
                        if c<Ge[i][s][b][r1+r2]:
                            Ge[i][s][b][r1+r2]=c; Gc[i][s][b][r1+r2]=(d,r1)
    for i in range(0,R-s+1):
        for r in range(0,C+1):
            best=INF; ch=None
            if s<=8:
                for m in range(3):
                    if not ok(i,s,m): continue
                    P=(32+s*WIDTH[m]+63)//64
                    c0=leaf(i,s,m,0)
                    if r==0 and c0<best: best=c0; ch=('leaf',m,0)
                    if r==P:
                        c1=leaf(i,s,m,1)
                        if c1<best: best=c1; ch=('leaf',m,1)
            for b in range(2,bmax+1):
                for m in range(3):
                    if not ok(i,s,m): continue
                    P=(32+4*b+(b-1)*WIDTH[m]+63)//64
                    c0=internal(i,s,b,m,0)
                    if Ge[i][s][b][r]<INF and c0+Ge[i][s][b][r]<best:
                        best=c0+Ge[i][s][b][r]; ch=('int',b,m,0)
                    if P<=r:
                        c1=internal(i,s,b,m,1)
                        if Ge[i][s][b][r-P]<INF and c1+Ge[i][s][b][r-P]<best:
                            best=c1+Ge[i][s][b][r-P]; ch=('int',b,m,1)
            Fe[i][s][r]=best; Fc[i][s][r]=ch
    for i in range(0,R-s+1):
        for r in range(0,C+1): Ge[i][s][1][r]=Fe[i][s][r]
for r in range(C+1):
